def is_authorized(user, resource):
    """Return True if `user` may read `resource`."""
    allowed = False
    try:
        if user["role"] == "admin":
            allowed = True
        else:
            owner = resource.get("owner")
            if owner == user["id"] or owner is None:
                allowed = True
    except KeyError:
        raise
    return allowed
